INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_duskmane','Grey at the muzzle and black down the spine, the old lord of the Rattelshof pack. He has never once been in a hurry.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_duskmane','Dead Duskmane, Lord of the Rattelshof Pack');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_duskmane','Duskmane, Lord of the Rattelshof Pack');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_cinderjaw','A black wolf with a scorched muzzle and eyes like coals. It fights at its lord''s right hand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_cinderjaw','Dead Cinderjaw');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_cinderjaw','Cinderjaw');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_gloomfang','A lean black wolf that seems to fade into the shadows between the trees. It fights at its lord''s left hand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_gloomfang','Dead Gloomfang');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_gloomfang','Gloomfang');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_duskborn_01','A black wolf of the Rattelshof hills, big and quiet.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_duskborn_01','Dead Duskborn Wolf');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_duskborn_01','Duskborn Wolf');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_duskborn_02','A black wolf of the Rattelshof hills, big and quiet.');
