INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_duskborn_10','Duskborn Wolf');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_wolf_charm','Witch''s Wolf-Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_wolf_charm','Owl feathers and red thread, braided into the alpha''s fur. The witches of the Dark Forest tie these on the wolves they keep. Knowall, their talking toad, will know what it means.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_greymaw','The alpha of the mad pack. Grey as iron, and it does not flinch from fire.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_greymaw','Dead Greymaw, the Mad Alpha');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_greymaw','Greymaw, the Mad Alpha');
