INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_madwolf_13','Moon-mad Hunter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5b06d998-8ddc-56e2-ae18-0b2c68521573','I took this charm from a mad wolf.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4fc13caf-89dc-5b6c-af92-217df75de21b','Croak! Mother''s charm, from the grey one. But Knowall still hears the white one, crackle crackle, in the west. Storm in its fur. Bring Knowall the charm when both are quiet. Croak.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('74ab6d44-7065-525c-992d-0e7687922f65','I found this charm in the fur of a mad wolf. The pack is dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b16f3725-8e5a-55fe-b3cc-e603ff3af656','Croak... Mother Alwene''s charm. Storm came down on the western woods and the wolves went bad, bad, eyes like coals. Knowall could not help. You helped. Mother left skins-and-sinew notes with Knowall for whoever ends it. Moon-mad pelt makes leather no blade bites, sinew makes a string that sings. Take, take. Knowall is thankful, croak, croak.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('439d034b-5705-5e05-94f0-503352c0f78e','The Mad Pack');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bbc6d8b9-46df-56ab-9aa4-32dff7c09ec5','The witches of the Dark Forest keep wolves, and something has driven them mad: they hunt as one pack in the western woods, led by the grey alpha Greymaw and the white wolf Stormhowl. The grey one wore a witch''s charm. Knowall, the witches'' talking toad, will know what it means.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5a0a4306-9c91-5010-8ae2-ff5c72b526ac','The mad pack is dead. Knowall gave me the witches'' notes on moon-mad pelt and sinew.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('442a63a2-4ee3-579c-b555-8fcce22ce371','Greymaw and Stormhowl');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8e4458ec-264a-5871-a1af-1233cf045f81','Kill the two leaders of the mad pack in the western woods. The rest of the pack will not stand aside.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5f7b2c68-7362-57f0-9fc4-365a9ecd29c7','Greymaw and Stormhowl are dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('58ee9ae1-938d-57a0-b44e-da996b7ae8e9','The Witch''s Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('80a0afbb-753d-5a82-bd6f-17c31f5a0a16','Bring the witch''s charm to Knowall, the witches'' talking toad.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4456fa9a-6749-5447-b3ec-2f4e7cc1773a','I gave Knowall the charm.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_tg_strongbox','The Dark Eyes'' Strongbox');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_tg_strongbox','A heavy iron strongbox with the Dark Eye sign on the lid. Cano wants it unopened.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_ulgar','Ulgar Crowsfoot, Dark Eye Lieutenant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_dehexer','Dark Eye Hedge-Witch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_darkeye1','Dark Eye Cutthroat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_darkeye2','Dark Eye Cutthroat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_darkeye3','Dark Eye Cutthroat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('57cd3faa-ac16-5b8a-a6ea-e8d9877bb3d4','Lost? This corner is taken. Walk on, and keep your hands where my friends can see them.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4804cc57-96a6-5141-94d4-966116b77a58','Cano sends his regards. Hand it over.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ffd4d5dd-bf34-5a1b-9359-5e27c8a6b7f7','Cano? Then he can have it back in pieces. Yours.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('15a9e27d-4823-58f8-b83f-6947da3c4995','Just passing through.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_silke','Silas Quickfingers, Guild Fence');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('316c4c9b-56f5-5e93-8b5c-216a1f5dfa89','Cano says you are one of us now. Good. I buy what you should not have and sell what nobody saw leave. Blades, stars, boots that keep quiet.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('67d9db5d-b038-5cdf-b1bd-bb58deaa050a','Show me what you have.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e4d4d2e5-8901-51c5-950a-dbd908c68a75','Teach me.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('85828e7c-cf1a-5140-af78-ce13dbacdd41','Later.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('44f47e0a-44b5-57af-95fe-ebcabd482729','Any work for someone with quiet hands?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3e3108e7-b903-5431-aa6d-c6c5d3499cef','There is a job, if you are as good as the rumours say. What is left of the Dark Eyes meets at the harbour, at their old deal spot, and their lieutenant Ulgar Crowsfoot carries the gang''s last strongbox wherever he goes. I want it. Lift it from his belt, quietly, or take it from his cold hands; Phex does not mind which, only the Dark Eyes will.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4e369e1c-bf8b-56b3-82a4-eb4601016203','Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('899dfbbd-7dc1-5344-af49-9e70022aeac7','Good. Quiet is better, but I will take loud. Bring it here, and nobody else needs to know.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a010b34c-cd04-5ddb-aec8-6042de06fcd0','Here it is: The Dark Eyes'' Strongbox.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bf66ad97-ad34-5e2f-8f64-9268c7a627e3','Ulgar''s strongbox! Unopened, too. You have a future here. Silas! Come down, we have a new friend. He is our fence: tell him I sent you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9e1f5da2-b3f0-5bf4-a6b5-56e47fa0516b','The Dark Eyes'' Strongbox');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('01f22da8-9ec0-534a-bbca-bf5d02cae09d','Cano wants The Dark Eyes'' Strongbox. Ulgar Crowsfoot, lieutenant of the Dark Eyes, carries it at their old deal spot in Ferdok harbour. Steal it from them unseen, or take it by force, and bring it to Cano.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8596b93e-ad3e-5c87-9d6c-9f01857e7196','Cano has The Dark Eyes'' Strongbox.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_tg_silver','The Baron''s Silver');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_tg_silver','Silver plate from Castle Grimmzahn''s treasury, wrapped in a soldier''s cloak.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_brackwald','Sergeant Brackwald, Deserter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_dshexer','Renegade Battle-Mage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_deserter1','Grimmzahn Deserter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_deserter2','Grimmzahn Deserter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_deserter3','Grimmzahn Deserter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_deserter4','Grimmzahn Deserter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2eb824f5-1965-5f75-b12d-e3f0968f3696','Lost? This corner is taken. Walk on, and keep your hands where my friends can see them.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('cf37dca5-ebd7-5da9-9aff-eade155cf6ae','Cano sends his regards. Hand it over.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d35882d0-747c-5052-8434-5b244bf59f23','Cano? Then he can have it back in pieces. Yours.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('29a4f69a-4f25-5dff-88fa-f67f6615de34','Just passing through.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_ravik','Ravik Blackstitch, Guild Tailor');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c3250a87-a75e-5fbe-a6c1-91908fc3f0e2','Iryan leather, the black kind. Cut close, oiled silent, no buckle to catch the moon. Buy the plans and the leather, and any workbench will do.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('07bc458c-2f70-5b68-adff-b4d02667f686','Show me what you have.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fd9a57a3-90aa-57dd-8ef2-c4dfe276744e','Teach me.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('53b49726-9e5a-56f6-b759-949630bfb8f5','Later.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('88e26dd5-a9c7-5768-8a2a-d76d017adf71','Do you have another job for me, Cano?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('22b596ea-8f27-5292-ae54-6041dc21af21','While the orcs were busy with Grimmzahn, a few of its own soldiers emptied the treasury and ran. Their sergeant, Brackwald, camps on the old road through the Blood Mountains with the Baron''s silver, waiting for the roads to clear. The silver should travel. With us. He keeps it on him, of course.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0f10773a-6d6c-5cb9-8dab-784180c60436','Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4e345216-4def-52e3-aec9-34eede6a2128','Good. Quiet is better, but I will take loud. Bring it here, and nobody else needs to know.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0f9a91ca-6e0c-5af3-95b7-896498f0c4c9','Here it is: The Baron''s Silver.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('53b5ae54-c25d-5985-8cbb-b53c4fdfb84c','The Baron''s silver. The Baron will never miss what he believes the orcs took. Ravik! Our new star needs clothes that do not rattle.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3ce38d33-4b9a-560d-88b5-e6223b9bd1a5','The Baron''s Silver');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c42b76da-01d4-5c3b-9030-52dceead91a1','Cano wants The Baron''s Silver. Sergeant Brackwald, a deserter, keeps it on him on the old road through the Blood Mountains. Steal it from them unseen, or take it by force, and bring it to Cano.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c8a96622-f2c9-5519-8660-a4daa3a753b7','Cano has The Baron''s Silver.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_tg_ledger','The Silent Hand''s Ledger');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_tg_ledger','Names, debts and bribes of the Silent Hand of Tallon, in a careful cipher.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_kessar','Master Kessar of the Silent Hand');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_shhexer','Silent Hand Hexer');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_silent1','Silent Hand Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_silent2','Silent Hand Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_silent3','Silent Hand Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_silent4','Silent Hand Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('061dd7db-ec57-53ae-b5b9-963fc2e010de','Lost? This corner is taken. Walk on, and keep your hands where my friends can see them.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('edcc31a3-de59-5b76-b2a0-f282787d49d3','Cano sends his regards. Hand it over.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f72e5920-b623-5d25-b4dd-fb3c2634b67e','Cano? Then he can have it back in pieces. Yours.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('af42e9d1-d36d-5fa8-9c03-fefcb2dce052','Just passing through.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_velane','Velane the Shade, Blade Master');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('86d6e014-e9c0-564d-af30-6b6bb7c2059e','Kessar paid me to teach his knives. You paid me by taking his ledger. So I teach you instead. It is a better use of my time.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5728d046-ef2b-57a4-aad9-ce58c55a7e69','Show me what you have.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1b0f7b2f-6e31-5f7a-b221-c3ef5fbf9e4c','Teach me.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5e61233a-d551-58e0-a051-cf6fb31b2a11','Later.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('94c40b06-e761-5239-971f-8b4505b7fa70','Do you have another job for me, Cano?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('66ec964c-fd55-52fe-8af2-fa0e24609766','Tallon has its own guild. The Silent Hand. They have been selling our people to the town watch for years, and their master Kessar keeps the ledger that proves it. He meets his knives in the rubble outside the walls. Bring me that ledger and their whole house of cards falls.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f4ef0629-d343-5d9c-8dbe-de0f95d655d0','Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f85dc495-fcff-5ac7-9d57-e131a901e85d','Good. Quiet is better, but I will take loud. Bring it here, and nobody else needs to know.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('985f2cbf-4eb5-5794-8207-a8b31d27f633','Here it is: The Silent Hand''s Ledger.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b49c37c8-ec5e-56d1-818a-b411ff558d62','Kessar''s ledger! Half of Tallon''s watch is in here. And look who came with you: Velane, his own blade master. She says she was tired of the company. She teaches now. Down there.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('aa6e9a9f-3740-5e32-be21-03918f50fe30','The Silent Hand''s Ledger');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e4d9a447-daa5-53fe-95e7-25da6d6ba559','Cano wants The Silent Hand''s Ledger. Master Kessar of the Silent Hand keeps it on him in the rubble outside Tallon. Steal it from them unseen, or take it by force, and bring it to Cano.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('cb657650-482f-5259-b520-806e7ad5942b','Cano has The Silent Hand''s Ledger.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_tg_crystal','Aldessia''s Portal Crystal');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_tg_crystal','A crystal that hums when you hold it near a doorway. Aldessia''s best-kept secret.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_morwena','Morwena, Aldessia''s Apprentice');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_apprentice1','Black Apprentice');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_hireling1','Hired Axe of Murolosh');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_hireling2','Hired Axe of Murolosh');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('42f65338-12e5-5dff-8701-f0a9915367ab','Lost? This corner is taken. Walk on, and keep your hands where my friends can see them.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fe88904d-0cdf-5721-8ff1-27ae4d3d5e58','Cano sends his regards. Hand it over.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('80c251c6-75f7-54e0-9596-0e02c4c0875c','Cano? Then he can have it back in pieces. Yours.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bc4a397d-05d6-54b9-bf9f-87654de03239','Just passing through.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_tg_wendrik','Old Fox Wendrik, Forger');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5455ab24-ee5f-5127-81e2-5cf3a2e8d733','Wendrik. Forger, jeweller, honest dwarf. Mostly honest. Everything on this table was made by hand, and none of it by mine.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('120f3de8-b9b9-528a-9381-c95dd5b84400','Show me what you have.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0b1fbe92-045e-51cc-8a40-1dd53a0e23c0','Teach me.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d21c69c1-7e98-5fa4-ba64-974eecff6c33','Later.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dee371c2-7670-508e-852e-a933b29f8f82','Do you have another job for me, Cano?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fe3fc759-7ead-5e12-8b5c-9704e09d5943','Aldessia is gone and her apprentices are picking her house clean before the dwarves think of it. The best piece in there is a crystal that opens her portals; her favourite, Morwena, wears it on a chain. Imagine what a guild can do with a door to anywhere. I can imagine it very well.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b8c6b1c6-c93a-5543-a595-cd0655bb918c','Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7f7de6ec-ec8c-5c2b-80a7-7df02d292137','Good. Quiet is better, but I will take loud. Bring it here, and nobody else needs to know.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6cc57f5a-835a-57ac-9263-109b8814c327','Here it is: Aldessia''s Portal Crystal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('43a2cc96-7301-55a8-b2c4-018c241042b4','A door to anywhere, and it fits in my pocket. Wendrik! Wake up, old fox, you have a customer. Our forger. He never touched anything in his life.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8d645b0f-4748-5f8c-b87c-d9a1a3243215','Aldessia''s Portal Crystal');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6e97cb04-fddf-54b5-8b70-bf7f1023609e','Cano wants Aldessia''s Portal Crystal. Morwena, Aldessia''s favourite apprentice, wears it while her gang empties Aldessia''s house in Murolosh. Steal it from them unseen, or take it by force, and bring it to Cano.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('caaeed8c-a620-513f-b842-b8457425b19f','Cano has Aldessia''s Portal Crystal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a98c8235-2db2-533b-af45-ea4a1343c8c0','Phex''s Due');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b617fe9e-ced9-5dc2-83f0-bde4c550da0d','Cano has work for me now that I have made a name for myself. The Guild of Thieves pays well, and it grows with every job I do.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('712dc615-b389-55c0-8209-4ef9a5402520','I have done four jobs for Cano. The whole guild knows my name.');
